UPDATE kb_conversation SET owner_user_id = #{ownerUserId}, title = #{title},
        create_request_id = #{createRequestId}, creation_digest = #{creationDigest}, last_turn_seq = #{lastTurnSeq},
        active_turn_id = #{activeTurnId}, execution_epoch = #{executionEpoch}, created_at = #{createdAt}, updated_at =
        #{updatedAt}, deleted_at = #{deletedAt}
        WHERE id = #{id}

UPDATE kb_conversation_settlement SET state = #{state}, next_attempt_at = #{next},
settled_at = #{settled}, claimed_until = NULL
WHERE turn_id = #{turn} AND state = 'PENDING' AND attempts = #{attempt}
AND claimed_until IS NOT DISTINCT FROM #{claim}
